#!/bin/bash

# Generated by dotbash
set -e

DRY_RUN=false
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=true ;;
  esac
done

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

dotbash_run() {
  if [ "$DRY_RUN" = true ]; then
    echo "[dry-run] $*"
  else
    "$@"
  fi
}

dotbash_configure_brew_path() {
  if [ -x /opt/homebrew/bin/brew ]; then
    eval "$(/opt/homebrew/bin/brew shellenv)"
  elif [ -x /usr/local/bin/brew ]; then
    eval "$(/usr/local/bin/brew shellenv)"
  fi
}

echo "Setting up: ~/.gitconfig -> git/.gitconfig"
if [ ! -e "$ROOT"/git/.gitconfig ]; then
  echo "  ✗ Error: Source does not exist: git/.gitconfig"
  exit 1
fi
if [ -L "$HOME/.gitconfig" ] && [ "$(readlink "$HOME/.gitconfig")" = "$ROOT"/git/.gitconfig ]; then
  echo "  ✓ Already linked ~/.gitconfig"
else
  if [ "$DRY_RUN" = true ]; then
    echo "  [dry-run] would link ~/.gitconfig -> git/.gitconfig"
  else
    mkdir -p "$(dirname "$HOME/.gitconfig")"
    if [ -e "$HOME/.gitconfig" ] || [ -L "$HOME/.gitconfig" ]; then
      echo "  Removing existing: ~/.gitconfig"
      rm -rf "$HOME/.gitconfig"
    fi
    ln -s "$ROOT"/git/.gitconfig "$HOME/.gitconfig"
    echo "  ✓ Linked ~/.gitconfig"
  fi
fi

echo "Setting up: ~/.gitignore_global -> git/.gitignore_global"
if [ ! -e "$ROOT"/git/.gitignore_global ]; then
