    if [ -e "$HOME/.config/git/delta/tokyonight_night.gitconfig" ] || [ -L "$HOME/.config/git/delta/tokyonight_night.gitconfig" ]; then
      echo "  Removing existing: ~/.config/git/delta/tokyonight_night.gitconfig"
