echo "Setting up: ~/.config/ghostty -> ghostty"
if [ ! -e "$ROOT"/ghostty ]; then
  echo "  ✗ Error: Source does not exist: ghostty"
  exit 1
fi
if [ -L "$HOME/.config/ghostty" ] && [ "$(readlink "$HOME/.config/ghostty")" = "$ROOT"/ghostty ]; then
  echo "  ✓ Already linked ~/.config/ghostty"
else
  if [ "$DRY_RUN" = true ]; then
    echo "  [dry-run] would link ~/.config/ghostty -> ghostty"
  else
    mkdir -p "$(dirname "$HOME/.config/ghostty")"
    if [ -e "$HOME/.config/ghostty" ] || [ -L "$HOME/.config/ghostty" ]; then
